import React, { useEffect, useState } from 'react';
import TimerOutlinedIcon from '@mui/icons-material/TimerOutlined';

export function formatStopwatch(milliseconds: number): string {
  const hundredths = Math.floor(Math.max(0, milliseconds) / 10);
  return `${String(Math.floor(hundredths / 6000)).padStart(2, '0')}:${String(Math.floor(hundredths / 100) % 60).padStart(2, '0')}.${String(hundredths % 100).padStart(2, '0')}`;
}

/** Only the clock repaints; typing, answer controls and their focus stay untouched. */
export default function GameStopwatch({
  label,
  startedAt,
  finishedAt,
  savedSeconds,
}: {
  label: string;
  startedAt?: number;
  finishedAt?: number;
  savedSeconds?: number | null;
}) {
  const [now, setNow] = useState(Date.now);
  useEffect(() => {
    if (startedAt === undefined || finishedAt !== undefined || savedSeconds !== undefined) {
      return;
    }
    let frame: number;
    const tick = () => {
      setNow(Date.now());
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [startedAt, finishedAt, savedSeconds]);
  const display =
    savedSeconds !== undefined
      ? savedSeconds === null
        ? '—'
        : formatStopwatch(savedSeconds * 1000).slice(0, -3)
      : startedAt === undefined
        ? '—'
        : formatStopwatch((finishedAt ?? now) - startedAt);
  return (
    <p className="game-stopwatch">
      <TimerOutlinedIcon aria-hidden="true" fontSize="inherit" />
      <span role="timer" aria-label={label} aria-live="off">
        {display}
      </span>
    </p>
  );
}
