import React, { useEffect, useState } from 'react';
import { Alert, Box, Snackbar } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import CloseIcon from '@mui/icons-material/Close';
import GameIconButton from './GameIconButton';
import { getModalSurface } from '../utils/modalSurface';
import { loadGameWings } from './GameWings';
import animation from '../assets/animations/angel-halo.lottie';
import logo from '../assets/logo512.png';

type Player = React.ComponentType<{
  src: string;
  loop: boolean;
  autoplay: boolean;
  style?: React.CSSProperties;
}>;

export default function GameFeedbackToast({
  event,
  message,
  closeLabel,
  onClose,
}: {
  event: number;
  message: string;
  closeLabel: string;
  onClose: () => void;
}) {
  const theme = useTheme();
  const [reducedMotion, setReducedMotion] = useState(
    () => window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches ?? true,
  );
  const [Animation, setAnimation] = useState<Player | null>(null);
  useEffect(() => {
    const motion = window.matchMedia?.('(prefers-reduced-motion: reduce)');
    const update = () => setReducedMotion(motion?.matches ?? true);
    motion?.addEventListener?.('change', update);
    return () => motion?.removeEventListener?.('change', update);
  }, []);
  useEffect(() => {
    if (!event || reducedMotion || Animation) {
      return;
    }
    let disposed = false;
    void loadGameWings()
      .then(({ DotLottieReact }) => {
        if (!disposed) {
          setAnimation(() => DotLottieReact);
        }
      })
      .catch(() => {
        /* The static mark and message remain usable without animation. */
      });
    return () => {
      disposed = true;
    };
  }, [event, reducedMotion, Animation]);
  if (!event) {
    return null;
  }
  return (
    <Snackbar
      key={event}
      open
      autoHideDuration={3200}
      disableWindowBlurListener
      TransitionProps={reducedMotion ? { timeout: 0 } : undefined}
      anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      onClose={(_, reason) => {
        if (reason !== 'clickaway') {
          onClose();
        }
      }}
      sx={{
        top: { xs: 'calc(env(safe-area-inset-top) + 72px)', sm: 88 },
        bottom: 'auto',
        left: '50%',
        right: 'auto',
        transform: 'translateX(-50%)',
        width: 300,
        maxWidth: 'calc(100vw - 32px)',
      }}
    >
      <Alert
        icon={false}
        role="status"
        aria-live="polite"
        sx={{
          ...getModalSurface(theme.palette.mode),
          width: '100%',
          alignItems: 'center',
          py: 0.5,
          '& .MuiAlert-message': { display: 'flex', alignItems: 'center', gap: 1, p: 0 },
          '& .MuiAlert-action': { p: 0, mr: 0, alignSelf: 'center' },
        }}
        action={
          <GameIconButton label={closeLabel} onClick={onClose}>
            <CloseIcon />
          </GameIconButton>
        }
      >
        <Box
          aria-hidden="true"
          sx={{
            width: 42,
            height: 42,
            flexShrink: 0,
            filter: theme.palette.mode === 'dark' ? 'invert(1)' : 'none',
          }}
        >
          {Animation && !reducedMotion ? (
            <Animation
              key={event}
              src={animation}
              loop={false}
              autoplay
              style={{ width: '100%', height: '100%' }}
            />
          ) : (
            <img src={logo} width="42" height="42" alt="" />
          )}
        </Box>
        <span>{message}</span>
      </Alert>
    </Snackbar>
  );
}
