export type GameKind = 'wordle' | 'blank' | 'flashcards';
export type QuizMode = 'blank' | 'easy' | 'medium' | 'hard';
export interface VerseReference {
  book: string;
  chapter: number;
  verse: number;
}
export interface GameVerse extends VerseReference {
  text: string;
  translation: string;
}
export interface Choice {
  id: string;
  label: string;
}
export interface Question {
  verse: GameVerse;
  mode: QuizMode;
  prompt: string;
  hint: string;
  choices: [Choice, Choice, Choice];
  answerId: string;
}
export const verseKey = (v: VerseReference): string => `${v.book}:${v.chapter}:${v.verse}`;
