import React from 'react';
import { IconButton, Tooltip } from '@mui/material';
import { verseActionButtonSx } from '../styles/verseUi';

export default function GameIconButton({
  label,
  onClick,
  disabled = false,
  children,
}: {
  label: string;
  onClick: () => void;
  disabled?: boolean;
  children: React.ReactNode;
}) {
  return (
    <Tooltip title={label} arrow describeChild>
      <span className="game-icon-control">
        <IconButton
          type="button"
          aria-label={label}
          onClick={onClick}
          disabled={disabled}
          disableRipple
          sx={[
            ...(Array.isArray(verseActionButtonSx) ? verseActionButtonSx : [verseActionButtonSx]),
            {
              width: 44,
              height: 44,
              flexShrink: 0,
              '&.Mui-focusVisible': { outline: '2px solid #5685b0', outlineOffset: 2 },
              '& .MuiSvgIcon-root': { fontSize: 20 },
              '@media (prefers-reduced-motion: reduce)': {
                transition: 'none',
                '&:hover, &:active': { transform: 'none' },
              },
            },
          ]}
        >
          {children}
        </IconButton>
      </span>
    </Tooltip>
  );
}
