import React, { useId } from 'react';
import GameSheet from './GameSheet';
import { GameCopy } from './gameCopy';

const HELP_ART = {
  blank: '/games/blank-illustration.webp',
  flashcards: '/games/flashcards-illustration.webp',
} as const;

function WordleLesson({ t }: { t: GameCopy }) {
  const rows = [
    {
      word: 'GRACE',
      marks: ['correct', '', '', '', ''] as const,
      focus: 'G',
      caption: t.correctPosition,
    },
    {
      word: 'PEACE',
      marks: ['', 'present', '', '', ''] as const,
      focus: 'E',
      caption: t.otherPosition,
    },
    {
      word: 'STONE',
      marks: ['', '', 'absent', '', ''] as const,
      focus: 'O',
      caption: t.absentLetter,
    },
  ];
  return (
    <div className="wordle-lesson">
      {rows.map((row) => (
        <div key={row.word}>
          <div className="wordle-example" aria-hidden="true">
            {row.word.split('').map((letter, index) => (
              <span
                className="wordle-cell"
                key={`${row.word}-${index}`}
                {...(row.marks[index] ? { 'data-letter': row.marks[index] } : {})}
              >
                {letter}
              </span>
            ))}
          </div>
          <p className="wordle-example-note">
            <strong>{row.focus}</strong> · {row.caption}
          </p>
        </div>
      ))}
    </div>
  );
}

export default function GameHelpDialog({
  open,
  onClose,
  onStart,
  t,
  game,
  children,
}: {
  open: boolean;
  onClose: () => void;
  onStart?: () => void;
  t: GameCopy;
  game: 'wordle' | 'blank' | 'flashcards';
  children?: React.ReactNode;
}) {
  const title = useId();
  const art =
    game === 'wordle' ? undefined : (
      <span className={`game-sheet-frame game-sheet-frame-${game}`}>
        <img src={HELP_ART[game]} alt="" width={768} height={512} />
      </span>
    );
  return (
    <GameSheet
      open={open}
      onClose={onClose}
      closeLabel={t.close}
      titleId={title}
      title={t.howToPlay}
      art={art}
    >
      <p className="game-sheet-lead">
        {game === 'wordle' ? t.englishHelp : game === 'blank' ? t.blankHelp : t.flashcardsHelp}
      </p>
      {game === 'wordle' && <WordleLesson t={t} />}
      {children}
      <hr className="game-sheet-rule" />
      <p className="game-sheet-note">{t.timerHelp}</p>
      {onStart && (
        <button className="game-sheet-action" type="button" onClick={onStart}>
          {t.start}
        </button>
      )}
    </GameSheet>
  );
}
