import { languageTag } from '../public-site/locales';
import { usePublicLanguage } from '../public-site/PublicLanguage';
import React, { useCallback, useEffect, useRef, useState } from 'react';
import GameIconButton from './GameIconButton';
import GameFeedbackToast from './GameFeedbackToast';
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined';
import ReplayIcon from '@mui/icons-material/Replay';
import PlayArrowOutlinedIcon from '@mui/icons-material/PlayArrowOutlined';
import KeyboardReturnIcon from '@mui/icons-material/KeyboardReturn';
import { getAuth } from 'firebase/auth';
import { subscribeToPublicSession } from '../public-site/publicSession';
import {
  requestAccountWordle,
  requestWordleLeaderboard,
  WordleLeader,
  WordleRequestError,
  WordleSubmission,
} from '../services/wordpress';
import {
  AccountWordle,
  addWordleGuess,
  elapsedWordleSeconds,
  formatWordleTime,
  startWordle,
  dailyWord,
  nextWordleDay,
  parseWordList,
  restoreWordle,
  scoreWordleGuess,
  utcDay,
  WordList,
  wordleOutcome,
} from './wordleEngine';
import GameConfetti from './GameConfetti';
import GameHelpDialog from './GameHelpDialog';
import GameSheet from './GameSheet';
import GameStopwatch from './GameStopwatch';
import {
  bindLeaderboardIntent,
  clearLeaderboardIntent,
  prepareLeaderboardSignup,
  readLeaderboardIntent,
  validPublicName,
  WORDLE_SIGNUP_URL,
  LeaderboardIntent,
} from './leaderboardIntent';
import { GameCopy } from './gameCopy';
import { readGameStorage, writeGameStorage } from './storage';

export default function WordleGame({
  t,
  leaderboardView = false,
  onViewChange,
  settings,
}: {
  t: GameCopy;
  leaderboardView?: boolean;
  onViewChange?: (leaderboard: boolean) => void;
  settings?: React.ReactNode;
}) {
  const [words, setWords] = useState<WordList | null>(null);
  const [failed, setFailed] = useState(false);
  const [retry, setRetry] = useState(0);
  const [uid, setUid] = useState<string | null>(null);
  const [day, setDay] = useState(utcDay);
  useEffect(
    () =>
      subscribeToPublicSession((status) => {
        setUid(status === 'signed-in' ? getAuth().currentUser?.uid || null : null);
      }),
    [],
  );
  useEffect(() => {
    const update = () => setDay(utcDay());
    const timer = setInterval(update, 15000);
    document.addEventListener('visibilitychange', update);
    return () => {
      clearInterval(timer);
      document.removeEventListener('visibilitychange', update);
    };
  }, []);
  useEffect(() => {
    const controller = new AbortController();
    let disposed = false;
    const timeout = setTimeout(() => controller.abort(), 12000);
    setFailed(false);
    void fetch('/games/wordle-v1.json', { signal: controller.signal })
      .then(async (response) => {
        if (!response.ok) {
          throw new Error('Word list unavailable');
        }
        const list = parseWordList(await response.json());
        if (!disposed) {
          setWords(list);
        }
      })
      .catch(() => {
        if (!disposed) {
          setFailed(true);
        }
      })
      .finally(() => clearTimeout(timeout));
    return () => {
      disposed = true;
      controller.abort();
      clearTimeout(timeout);
    };
  }, [retry]);
  if (!words) {
    return (
      <div className="game-panel" role="status">
        {failed ? (
          <>
            {t.unavailable}{' '}
            <GameIconButton label={t.retry} onClick={() => setRetry((n) => n + 1)}>
              <ReplayIcon />
            </GameIconButton>
          </>
        ) : (
          t.loading
        )}
      </div>
    );
  }
  return (
    <DailyWordle
      key={`${uid || 'guest'}:${day}`}
      words={words}
      day={day}
      uid={uid}
      t={t}
      leaderboardView={leaderboardView}
      onViewChange={onViewChange}
      settings={settings}
    />
  );
}

export function DailyWordle({
  words,
  day,
  uid,
  t,
  leaderboardView = false,
  onViewChange,
  settings,
}: {
  words: WordList;
  day: string;
  uid: string | null;
  t: GameCopy;
  leaderboardView?: boolean;
  onViewChange?: (leaderboard: boolean) => void;
  settings?: React.ReactNode;
}) {
  const { href, locale } = usePublicLanguage();
  const guestKey = `revelationary.wordle.v1.guest.${day}`;
  const storageKey = `revelationary.wordle.v1.${uid || 'guest'}.${day}`;
  const [state, setState] = useState(() =>
    restoreWordle(
      readGameStorage(storageKey) || (uid ? readGameStorage(guestKey) : null),
      day,
      words.words,
      words.allowedGuesses,
    ),
  );
  const [burst, setBurst] = useState(0);
  const [feedbackEvent, setFeedbackEvent] = useState(0);
  const [helpOpen, setHelpOpen] = useState(
    () => !state.startedAt && !state.guesses.length && !leaderboardView,
  );
  const [invite, setInvite] = useState(false);
  const inviteOffered = useRef(false);
  const inviteButton = useRef<HTMLButtonElement>(null);
  const [boardOpen, setBoardOpen] = useState(leaderboardView);
  const boardSummary = useRef<HTMLHeadingElement | null>(null);
  const intentAttempt = useRef(false);
  const [draft, setDraft] = useState('');
  const [account, setAccount] = useState<AccountWordle | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<keyof GameCopy | null>(null);
  const [storageError, setStorageError] = useState(false);
  const [listed, setListed] = useState(false);
  const [name, setName] = useState('');
  const [leaders, setLeaders] = useState<WordleLeader[] | null>(null);
  const [boardError, setBoardError] = useState(false);
  const [reload, setReload] = useState(0);
  const [boardReload, setBoardReload] = useState(0);
  const lifetime = useRef<AbortController | null>(null);
  const submitLock = useRef(false);
  const input = useRef<HTMLInputElement>(null);
  const localOutcome = wordleOutcome(state, words.words);
  const result = account?.today;
  const finished = !!result || localOutcome !== 'playing';
  const outcome = result?.outcome || localOutcome;
  const attempts = result?.attempts || state.guesses.length;
  const answer = dailyWord(day, words.words);
  const elapsed = result ? (result.elapsedSeconds ?? null) : elapsedWordleSeconds(state);
  const dailyBoardVisible = leaders !== null && (!boardError || leaders.length > 0);
  const resultVisible = finished && !boardOpen;
  const started = state.startedAt !== undefined || state.guesses.length > 0;
  const resetLabel = new Intl.DateTimeFormat(languageTag(locale), {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'UTC',
    hourCycle: 'h23',
    timeZoneName: 'short',
  }).format(new Date(nextWordleDay(day)));
  const closeInvite = () => {
    inviteOffered.current = true;
    setInvite(false);
    setListed(result?.listed || false);
  };
  const openInvite = () => {
    inviteOffered.current = true;
    setMessage(null);
    setInvite(true);
    setListed(true);
  };
  const retryAccount = () => {
    intentAttempt.current = false;
    setAccount(null);
    setReload((count) => count + 1);
  };
  const revealBoard = useCallback(() => {
    setBoardOpen(true);
    onViewChange?.(true);
  }, [onViewChange]);
  useEffect(() => {
    setBoardOpen(leaderboardView);
  }, [leaderboardView]);
  useEffect(() => {
    if (inviteOffered.current || boardOpen || !finished || outcome !== 'won') {
      return;
    }
    inviteOffered.current = true;
    setInvite(true);
    if (!result?.listed) {
      setListed(true);
    }
  }, [boardOpen, finished, outcome, result?.listed]);
  useEffect(() => {
    if (!boardOpen) {
      return;
    }
    setFeedbackEvent(0);
    const frame = requestAnimationFrame(() => {
      boardSummary.current?.focus();
    });
    return () => cancelAnimationFrame(frame);
  }, [boardOpen]);
  useEffect(() => {
    setStorageError(!writeGameStorage(storageKey, state));
  }, [storageKey, state]);
  useEffect(() => {
    const controller = new AbortController();
    lifetime.current = controller;
    const timeout = setTimeout(() => controller.abort(), 15000);
    if (uid) {
      setBusy(true);
      void requestAccountWordle(undefined, controller.signal)
        .then((value) => {
          if (!controller.signal.aborted) {
            setAccount(value);
            if (value.today) {
              setHelpOpen(false);
            }
            setListed(value.today?.listed || false);
            setName(value.today?.publicName || '');
            setMessage(null);
          }
        })
        .catch(() => {
          if (lifetime.current === controller) {
            setMessage('unavailable');
          }
        })
        .finally(() => {
          clearTimeout(timeout);
          if (lifetime.current === controller) {
            setBusy(false);
          }
        });
    } else {
      clearTimeout(timeout);
    }
    return () => {
      lifetime.current = null;
      controller.abort();
      clearTimeout(timeout);
    };
  }, [uid, reload]);
  useEffect(() => {
    const controller = new AbortController();
    let disposed = false;
    const timeout = setTimeout(() => controller.abort(), 12000);
    setBoardError(false);
    void requestWordleLeaderboard(controller.signal)
      .then((rows) => {
        if (!disposed) {
          setLeaders(rows);
          setBoardError(false);
        }
      })
      .catch(() => {
        if (!disposed) {
          setLeaders((current) => {
            if (current === null) {
              setBoardError(true);
            }
            return current;
          });
        }
      })
      .finally(() => clearTimeout(timeout));
    return () => {
      disposed = true;
      controller.abort();
      clearTimeout(timeout);
    };
  }, [boardReload]);
  const submitGuess = (event: React.FormEvent) => {
    event.preventDefault();
    if (!started || finished || draft.length !== 5) {
      return;
    }
    const guess = draft.toUpperCase();
    if (!words.allowedGuesses.includes(guess)) {
      setMessage(null);
      setFeedbackEvent((event) => event + 1);
      return;
    }
    setFeedbackEvent(0);
    const next = addWordleGuess(state, guess, words);
    setState(next);
    if (wordleOutcome(next, words.words) !== 'playing') {
      setBurst((n) => n + 1);
      if (wordleOutcome(next, words.words) === 'won') {
        openInvite();
      }
    }
    setDraft('');
    setMessage(null);
    input.current?.focus();
  };
  const commitScore = useCallback(
    async (update: WordleSubmission, intent?: LeaderboardIntent) => {
      if (!uid || submitLock.current) {
        return;
      }
      if (update.day !== utcDay()) {
        setMessage('expiredResult');
        return;
      }
      const controller = lifetime.current;
      if (!controller || controller.signal.aborted) {
        setMessage('unsaved');
        return;
      }
      submitLock.current = true;
      setBusy(true);
      setMessage(null);
      const timeout = setTimeout(() => controller.abort(), 15000);
      try {
        const value = await requestAccountWordle(update, controller.signal);
        if (
          value.day !== update.day ||
          !value.today ||
          value.today.listed !== update.listed ||
          value.today.publicName !== update.publicName
        ) {
          throw new Error('Publication was not confirmed');
        }
        if (!controller.signal.aborted) {
          setAccount(value);
          setListed(value.today?.listed || false);
          setName(value.today?.publicName || '');
          setBoardReload((n) => n + 1);
          clearLeaderboardIntent(uid, intent?.day || update.day);
          setInvite(false);
          if (update.listed) {
            setMessage('published');
            setInvite(false);
            revealBoard();
          }
        }
      } catch (error) {
        if (lifetime.current !== controller) {
          return;
        }
        setMessage('unsaved');
        if (error instanceof WordleRequestError && error.status === 409) {
          try {
            const current = await requestAccountWordle(undefined, controller.signal);
            if (!controller.signal.aborted) {
              setAccount(current);
              setListed(current.today?.listed || false);
              setName(current.today?.publicName || '');
              setMessage('conflict');
            }
          } catch {
            /* Keep local results for an explicit retry. */
          }
        }
      } finally {
        clearTimeout(timeout);
        submitLock.current = false;
        if (lifetime.current === controller) {
          setBusy(false);
        }
      }
    },
    [uid, revealBoard],
  );
  const save = () => {
    if (!uid || busy || !account || !finished || (listed && !validPublicName(name))) {
      return;
    }
    if (account.day !== state.day || utcDay() !== state.day) {
      setMessage('expiredResult');
      return;
    }
    void commitScore({
      day: account.day,
      revision: result?.revision || 0,
      guesses: result ? null : state.guesses,
      elapsedSeconds: result ? (result.elapsedSeconds ?? null) : elapsedWordleSeconds(state),
      listed,
      publicName: listed ? name.trim() : '',
    });
  };
  const signup = () => {
    if (!prepareLeaderboardSignup(state, name, words)) {
      setMessage('intentStorageError');
      return;
    }
    window.location.assign(href(WORDLE_SIGNUP_URL));
  };
  useEffect(() => {
    if (!leaderboardView || !uid || !account || busy || intentAttempt.current) {
      return;
    }
    intentAttempt.current = true;
    const intent = readLeaderboardIntent();
    if (!intent) {
      return;
    }
    if (intent.day !== day || account.day !== day || day !== utcDay()) {
      setMessage('expiredResult');
      return;
    }
    if (intent.owner !== null && intent.owner !== uid) {
      setMessage('intentAccountChanged');
      return;
    }
    const guest = restoreWordle(readGameStorage(guestKey), day, words.words, words.allowedGuesses);
    if (wordleOutcome(guest, words.words) !== 'won') {
      setMessage('intentMissing');
      return;
    }
    const bound = bindLeaderboardIntent(intent, uid);
    if (!bound) {
      setMessage('intentStorageError');
      return;
    }
    const seconds = elapsedWordleSeconds(guest);
    const existing = account.today;
    if (
      existing &&
      (existing.outcome !== 'won' ||
        existing.attempts !== guest.guesses.length ||
        (existing.elapsedSeconds ?? null) !== seconds)
    ) {
      setMessage('conflict');
      return;
    }
    setListed(true);
    setName(bound.publicName);
    void commitScore(
      {
        day,
        revision: existing?.revision || 0,
        guesses: existing ? null : guest.guesses,
        elapsedSeconds: seconds,
        listed: true,
        publicName: bound.publicName,
      },
      bound,
    );
  }, [leaderboardView, uid, account, busy, day, guestKey, words, commitScore]);
  return (
    <div className="game-panel wordle-panel">
      <GameConfetti burst={burst} />
      <GameFeedbackToast
        event={boardOpen ? 0 : feedbackEvent}
        message={t.invalid}
        closeLabel={t.close}
        onClose={() => setFeedbackEvent(0)}
      />
      <GameHelpDialog
        open={helpOpen && !boardOpen}
        onClose={() => setHelpOpen(false)}
        onStart={
          !started && !finished
            ? () => {
                setState((current) => startWordle(current));
                setHelpOpen(false);
              }
            : undefined
        }
        t={t}
        game="wordle"
      >
        {!started && !finished && settings}
      </GameHelpDialog>
      <div role="tabpanel" id="game-content" aria-labelledby="game-tab" hidden={boardOpen}>
        <div className="game-toolbar wordle-toolbar">
          <GameStopwatch
            label={t.time}
            startedAt={state.startedAt}
            finishedAt={state.finishedAt}
            savedSeconds={
              result &&
              !(
                result.outcome === localOutcome &&
                result.attempts === state.guesses.length &&
                result.elapsedSeconds === elapsedWordleSeconds(state) &&
                state.finishedAt !== undefined
              )
                ? (result.elapsedSeconds ?? null)
                : undefined
            }
          />
          <GameIconButton label={t.howToPlay} onClick={() => setHelpOpen(true)}>
            <InfoOutlinedIcon />
          </GameIconButton>
        </div>
        <p className="game-hint wordle-date">
          <time dateTime={day}>{day}</time> · UTC
        </p>
        {storageError && <p role="status">{t.storage}</p>}
        {!started && !finished && (
          <button className="game-action" onClick={() => setHelpOpen(true)}>
            <PlayArrowOutlinedIcon aria-hidden="true" />
            {t.start}
          </button>
        )}
        {(started || finished) && (
          <form onSubmit={submitGuess}>
            <div className="wordle-board" aria-label={t.wordle}>
              {Array.from({ length: 6 }, (_, row) => {
                const guess =
                  state.guesses[row] || (row === state.guesses.length && !finished ? draft : '');
                const feedback = state.guesses[row] ? scoreWordleGuess(answer, guess) : null;
                return (
                  <div className="wordle-row" key={row}>
                    {Array.from({ length: 5 }, (_, col) => (
                      <span
                        className="wordle-cell"
                        key={col}
                        data-letter={feedback?.[col]}
                        role={feedback ? 'img' : undefined}
                        aria-label={
                          feedback
                            ? `${guess[col]}: ${t[feedback[col] === 'correct' ? 'correctPosition' : feedback[col] === 'present' ? 'otherPosition' : 'absentLetter']}`
                            : undefined
                        }
                      >
                        {guess[col]}
                      </span>
                    ))}
                  </div>
                );
              })}
              {!finished && (
                <input
                  ref={input}
                  style={{ top: `calc(${state.guesses.length} * (100% + 6px) / 6)` }}
                  className="wordle-input"
                  aria-label={t.guess}
                  value={draft}
                  maxLength={5}
                  autoComplete="off"
                  autoCorrect="off"
                  autoCapitalize="characters"
                  spellCheck={false}
                  enterKeyHint="done"
                  onChange={(e) =>
                    setDraft(
                      e.target.value
                        .replace(/[^a-z]/gi, '')
                        .toUpperCase()
                        .slice(0, 5),
                    )
                  }
                />
              )}
            </div>
            {!finished && (
              <button
                className="wordle-enter game-action"
                type="submit"
                disabled={draft.length !== 5}
              >
                <KeyboardReturnIcon aria-hidden="true" />
                {t.submit}
              </button>
            )}
          </form>
        )}
        {finished && (
          <div className="wordle-result" role="status">
            <p className="wordle-result-outcome">{outcome === 'won' ? t.won : t.lost}</p>
            <p className="wordle-result-score">{outcome === 'won' ? `${attempts}/6` : 'X/6'}</p>
            <p className="wordle-result-answer">
              {answer.split('').map((letter, index) => (
                <span key={`${letter}-${index}`}>{letter}</span>
              ))}
            </p>
            <p className="wordle-result-next">
              {t.reset}
              <time dateTime={nextWordleDay(day)}>{resetLabel}</time>
            </p>
            {outcome === 'won' && (
              <button
                className="wordle-result-action"
                ref={inviteButton}
                type="button"
                onClick={openInvite}
              >
                {result?.listed ? t.join : t.addMyScore}
              </button>
            )}
            {message && !invite && !boardOpen && <p className="wordle-result-note">{t[message]}</p>}
            {uid && !busy && !account && !invite && !boardOpen && (
              <span className="wordle-result-retry">
                <GameIconButton label={t.retry} onClick={retryAccount}>
                  <ReplayIcon />
                </GameIconButton>
              </span>
            )}
            {uid && (
              <p className="wordle-result-account">
                {busy ? t.loading : result ? t.saved : t.unsaved}
              </p>
            )}
          </div>
        )}
      </div>
      {message &&
        !invite &&
        !resultVisible &&
        !(boardOpen && dailyBoardVisible && message === 'unavailable') && (
          <p role="status">{t[message]}</p>
        )}
      {uid &&
        !busy &&
        !resultVisible &&
        ((!account && !(boardOpen && dailyBoardVisible)) ||
          (leaderboardView && (message === 'unsaved' || message === 'intentStorageError'))) && (
          <GameIconButton label={t.retry} onClick={retryAccount}>
            <ReplayIcon />
          </GameIconButton>
        )}
      <GameSheet
        open={invite && finished && outcome === 'won'}
        onClose={closeInvite}
        closeLabel={t.close}
        titleId="wordle-invitation-title"
        title={t.inviteLeaderboard}
        align="center"
        onExited={() => {
          if (message === 'published') {
            revealBoard();
          } else {
            inviteButton.current?.focus();
          }
        }}
        art={
          <span className={`game-sheet-frame ${uid ? 'is-tiles' : 'is-stats'}`}>
            <img
              src={uid ? '/games/wordle-account-modal.webp' : '/games/wordle-stats-modal.webp'}
              alt=""
              width={1024}
              height={1024}
            />
          </span>
        }
      >
        {!uid && <p className="game-sheet-lead">{t.signin}</p>}
        <div className="game-sheet-form">
          <label>
            {t.name}
            <input
              value={name}
              maxLength={24}
              autoComplete="off"
              onChange={(e) => setName(e.target.value)}
            />
          </label>
          <p>
            {t.preview}: <strong>{name || '…'}</strong> · {attempts}/6 · {formatWordleTime(elapsed)}
          </p>
          <p className="game-hint">{t.privacy}</p>
          {uid && (
            <label className="game-check">
              <input
                type="checkbox"
                checked={listed}
                onChange={(e) => setListed(e.target.checked)}
              />
              {t.join}
            </label>
          )}
          {message && <p role="status">{t[message]}</p>}
        </div>
        <button
          className="game-sheet-action"
          type="button"
          disabled={
            uid ? busy || !account || (listed && !validPublicName(name)) : !validPublicName(name)
          }
          onClick={uid ? save : signup}
        >
          {uid ? (listed ? t.publishScore : t.save) : t.createAccountPublish}
        </button>
        <button className="game-sheet-quiet" type="button" onClick={closeInvite}>
          {t.notNow}
        </button>
        {!uid && <p className="game-sheet-note">{t.existingAccountHint}</p>}
      </GameSheet>
      <div hidden={boardOpen}>
        {!uid ? (
          !finished && (
            <p>
              <a href={href('/study/#/login?redirect=games')}>{t.signin}</a>
            </p>
          )
        ) : (
          <>
            {!finished && <p role="status">{busy ? t.loading : result ? t.saved : t.unsaved}</p>}
            {account && (
              <div className="wordle-stats">
                <span>
                  {t.streak}: {account.currentStreak}
                </span>
                <span>
                  {t.longest}: {account.longestStreak}
                </span>
              </div>
            )}
            {account && finished && outcome === 'won' && !result && !invite && (
              <button disabled={busy} onClick={save}>
                {t.save}
              </button>
            )}
            {account && finished && outcome !== 'won' && (
              <button disabled={busy} onClick={save}>
                {t.save}
              </button>
            )}
            {!!account?.trophies.length && (
              <div>
                <h3>{t.trophies}</h3>
                <ul>
                  {account.trophies.map((trophy) => (
                    <li key={trophy}>
                      ◇ {t[trophy as 'firstWin' | 'threeStreak' | 'sevenStreak']}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </>
        )}
      </div>
      <section
        className="wordle-leaders"
        role="tabpanel"
        id="leaderboard-content"
        aria-labelledby="leaderboard-tab"
        hidden={!boardOpen}
      >
        <h2 ref={boardSummary} tabIndex={-1}>
          {t.leaderboard}
        </h2>
        <p className="game-hint">{t.rankingHelp}</p>
        {dailyBoardVisible ? (
          leaders.length > 0 ? (
            <ol>
              {leaders.map((row, i) => (
                <li key={i} value={row.rank}>
                  {row.name}
                  <span>
                    {row.guesses}/6 · {formatWordleTime(row.elapsedSeconds)}
                  </span>
                </li>
              ))}
            </ol>
          ) : (
            <p>{t.noScores}</p>
          )
        ) : boardError ? (
          <p>
            {t.unavailable}{' '}
            <GameIconButton label={t.retry} onClick={() => setBoardReload((n) => n + 1)}>
              <ReplayIcon />
            </GameIconButton>
          </p>
        ) : (
          <p>{t.loading}</p>
        )}
      </section>
    </div>
  );
}
